<footer class="directory-pagination"><span>Affichage de {{ $paginator->firstItem()??0 }} à {{ $paginator->lastItem()??0 }} sur {{ $paginator->total() }} résultats</span><div>@if($paginator->previousPageUrl())<a href="{{ $paginator->previousPageUrl() }}" aria-label="Page précédente">‹</a>@endif @for($page=max(1,$paginator->currentPage()-2);$page<=min($paginator->lastPage(),$paginator->currentPage()+2);$page++)<a class="{{ $page===$paginator->currentPage()?'active':'' }}" href="{{ $paginator->url($page) }}">{{ $page }}</a>@endfor @if($paginator->nextPageUrl())<a href="{{ $paginator->nextPageUrl() }}" aria-label="Page suivante">›</a>@endif</div><label>Éléments par page <select data-page-size>@foreach(array_unique([8,10,25,50,$paginator->perPage()]) as $n)<option value="{{ $n }}" @selected($paginator->perPage()===$n)>{{ $n }}</option>@endforeach</select></label></footer>
